 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    top_cols = {c for r, c in marks if r == 0}
    bottom_cols = {c for r, c in marks if r == h - 1}
    left_rows = {r for r, c in marks if c == 0}
    right_rows = {r for r, c in marks if c == w - 1}
    cols, rows = top_cols & bottom_cols, left_rows & right_rows

    labels = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or labels[r][c] != -1:
                continue
            idx = len(components)
            stack = [(r, c)]
            labels[r][c] = idx
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and labels[ny][nx] == -1:
                        labels[ny][nx] = idx
                        stack.append((ny, nx))
            components.append(cells)

    # Recolor each full 2-object crossed by a marker-to-marker line.
    hit = set()
    for r in rows:
        for c in range(w):
            if grid[r][c] == 2:
                hit.add(labels[r][c])
    for c in cols:
        for r in range(h):
            if grid[r][c] == 2:
                hit.add(labels[r][c])
    for idx in hit:
        for r, c in components[idx]:
            out[r][c] = 1
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
